export type FacilityListResponse = {
    /**
     * Always list: identifies this facility list response.
     */
    action: 'list';
    /**
     * Facilities here owned by an allied faction that has turned on ally_facility_access for your faction. You queue jobs on them free: production.rental_fee_per_run is 0 and no output price is quoted, even when the facility is also publicly rentable to strangers. Your jobs still queue behind the owner's own work like a renter's. An ally facility is listed here and never under public_facilities. Omitted when there are none.
     */
    ally_facilities?: Array<FacilityEntry>;
    /**
     * Canonical ID of the station containing every listed facility and both per-station rent summaries.
     */
    base_id: string;
    /**
     * Station-owned facilities under construction here and the station manager's next planned build with the materials it still lacks. Your own and your faction's builds are not included; they appear in player_facilities and faction_facilities with under_construction. Omitted when the station is building nothing.
     */
    construction?: StationConstructionResponse;
    /**
     * Your faction's facilities at this base including paused facilities. Per-facility rent_per_cycle is the stored rate; faction_rent totals only currently billable facilities. Empty means your faction owns none here.
     */
    faction_facilities: Array<FacilityEntry>;
    /**
     * Current recurring rent and existing arrears for faction_facilities. Omitted when your faction owns no facilities here; present with zero recurring rent when all its facilities have paused billing.
     */
    faction_rent?: FacilityRentSummary;
    /**
     * Station life support: supply against demand, plant count and the upkeep its plants need. Omitted when the station has no life support supply, demand or plants.
     */
    life_support?: StationLifeSupportStatus;
    /**
     * Your facilities at this base including damaged and constructing and dismantling facilities. Per-facility rent_per_cycle is the stored rate; player_rent totals only currently billable facilities. Empty means you own none here.
     */
    player_facilities: Array<FacilityEntry>;
    /**
     * Current recurring rent and existing arrears for player_facilities. Omitted when you own no facilities here; present with zero recurring rent when all your facilities have paused billing.
     */
    player_rent?: FacilityRentSummary;
    /**
     * Station power grid: supply, current draw, battery and efficiency. While efficiency is below 1 every production facility and recycler here is slowed and shows power_throttled. Omitted when the station has no power supply, draw or battery capacity.
     */
    power?: StationPowerStatus;
    /**
     * Other players' facilities here with public access, plus other factions' publicly rentable facilities, so you can compare throughput, backlog and rental_fee_per_run before you queue a job. A disguised faction facility also appears here under its cover identity whether or not it is rentable. Owner rent fields are withheld. Omitted when there are none.
     */
    public_facilities?: Array<FacilityEntry>;
    /**
     * Finite shared station pools for personnel recruitment, marine training and medical treatment, with stock, refill rate and supply need; the medical pool also carries current per-patient treatment prices. Each pool is omitted when the station has no capacity for it; the whole block is omitted when it has none.
     */
    service_pools?: StationServicePools;
    /**
     * Facilities the station itself owns at this base: its services, infrastructure, defenses and generic production on-ramps. They bill you no rent; rent fields are omitted on them. Empty when the station owns none.
     */
    station_facilities: Array<FacilityEntry>;
};

