export type FacilityProduction = {
    /**
     * Estimated ticks to finish the whole current queue at the current speed, counting progress already made. A new job waits about this long if it queues behind everything. 0 when the queue is empty or the facility cannot run.
     */
    backlog_ticks: number;
    /**
     * Sustained output in items per real hour at the current speed and tick rate: runs per hour times output_per_run, rounded down. Omitted when zero: for recyclers, Logistics facilities and a facility that cannot run.
     */
    items_per_hour?: number;
    /**
     * Items one run produces: the sum of the recipe's output quantities. Omitted for recyclers and Logistics facilities.
     */
    output_per_run?: number;
    /**
     * Credits per package operation (one pack or unpack job) that the owner set on a player or faction Logistics facility. Never a per-item price. Omitted when no price is set, on non-Logistics facilities and on every ally_facilities entry.
     */
    output_price_per_operation?: number;
    /**
     * Credits per produced unit that the owner set with set_output_price on a player or faction facility. Present whenever a price is set, even while private or set to 0 (free). Omitted when no price is set, on station facilities, on Logistics facilities and on every ally_facilities entry.
     */
    output_price_per_unit?: number;
    /**
     * Pack operations this Logistics facility can finish per real hour at its current speed, rounded down. Omitted (0) for facilities that are not Logistics and for a Logistics facility that cannot run.
     */
    pack_operations_per_hour?: number;
    /**
     * True when outside players can rent this facility's spare capacity: a generic station facility, or one whose owner set access to public. Station infrastructure that is unique or empire-restricted is never public. Omitted means false.
     */
    public?: boolean;
    /**
     * Items the queued runs will produce in total. 0 when the queue is empty.
     */
    queued_items: number;
    /**
     * Runs still to do across every queued job at this facility, from all orderers (owner and renters). 0 means the queue is empty.
     */
    queued_runs: number;
    /**
     * Display name of the recipe this facility runs (for example Cultivate Bioluminescent Algae); the ID is recipe_id on the entry. Package Operations for a Logistics facility. Omitted for recyclers, which choose a recipe per job.
     */
    recipe?: string;
    /**
     * Credits charged per run to queue a job here as an outside renter. Present for publicly rentable facilities, including your own and your faction's so you can confirm the price you set. Omitted (0) when the facility is not publicly rentable, when the owner rents it out free, and on every ally_facilities entry, because an allied grant lets you queue there free.
     */
    rental_fee_per_run?: number;
    /**
     * Ticks one run takes at the facility's current speed: the recipe's crafting time divided by level throughput, station power efficiency and any faction admin bonus. For Logistics it is one pack operation. Omitted for recyclers and while the facility cannot run (under construction or no station power). Still reported while damaged, although a damaged facility does not run.
     */
    ticks_per_run?: number;
    /**
     * Unpack operations this Logistics facility can finish per real hour at its current speed, rounded down. Omitted (0) for facilities that are not Logistics and for a Logistics facility that cannot run.
     */
    unpack_operations_per_hour?: number;
};

