export type FindRouteResponse = {
    /**
     * Cargo units your current ship is carrying now. 0 when found is false or you have no ship.
     */
    cargo_used: number;
    /**
     * Fuel the whole route needs: fuel_per_jump times total_jumps. 0 when you are already there or found is false.
     */
    estimated_fuel: number;
    /**
     * Per-member fuel check over this route, yourself included. Present only when you lead a fleet with more than one member and a route was found; members without a ship are skipped. Omitted otherwise.
     */
    fleet_fuel?: Array<FleetMemberFuel>;
    /**
     * True when a route exists, including when you are already in the target system. False means no path was found; route is then empty and the fuel fields are 0.
     */
    found: boolean;
    /**
     * Fuel in your current ship's tank now. Compare with estimated_fuel to see whether you can finish the route without refueling. 0 when found is false or you have no ship.
     */
    fuel_available: number;
    /**
     * Fuel your current ship burns per jump, with your ship class, module and skill fuel bonuses applied; at least 1. The jump itself charges this amount. 0 when found is false or you have no ship.
     */
    fuel_per_jump: number;
    /**
     * Human-readable summary of the result, including the jump count and any final travel step.
     */
    message: string;
    /**
     * Systems in order from your current system to target_system, both included; see RouteStep. It holds a single step when you are already there. Normal connections and wormholes you know count as one jump each. Empty when found is false.
     */
    route: Array<RouteStep>;
    /**
     * POI ID to travel to after the last jump. Present only when you asked for a POI or base ID; a base resolves to the POI it sits at. Omitted for a system target.
     */
    target_poi?: string;
    /**
     * Display name of target_poi. Present exactly when target_poi is present.
     */
    target_poi_name?: string;
    /**
     * Canonical ID of the destination system. If you asked for a POI or base, this is the system that contains it.
     */
    target_system: string;
    /**
     * Jumps the route takes: the number of steps in route minus 1. 0 when you are already in the target system or found is false.
     */
    total_jumps: number;
};

export type FitIssue = {
    /**
     * The error code install_mod or uninstall_mod returns for the same problem: cpu_exceeded, power_exceeded, no_weapon_slots, no_defense_slots, no_utility_slots, module_limit, module_withdrawn, cargo_capacity_exceeded, personnel_capacity_exceeded, or no_safe_order when the fit is valid but no refit order reaches it
     */
    code: string;
    /**
     * Human-readable explanation with the numbers involved
     */
    message: string;
};

export type FitPreviewResponse = {
    /**
     * Every reason the planned fit is refused. Empty when valid
     */
    issues: Array<FitIssue>;
    /**
     * Your active ship, the one the plan is for
     */
    ship_id: string;
    /**
     * Ship stats with exactly the planned modules fitted. Reported for invalid plans too
     */
    stats: FitPreviewStats;
    /**
     * An order of uninstall_mod and install_mod calls that reaches the planned fit without any call being refused for CPU, power, slots or personnel capacity. Cargo limits are checked against your hold as it is now: modules moving into and out of cargo during the steps are not counted, so keep room in your hold. Run the steps in order, one per tick. Empty when the plan is invalid or already matches the current fit
     */
    steps: Array<FitPreviewStep>;
    /**
     * True when the planned fit passes every install_mod and uninstall_mod fit check. Equivalent to issues being empty
     */
    valid: boolean;
};

export type FitPreviewStats = {
    /**
     * Armor with the planned modules fitted
     */
    armor: number;
    /**
     * Total cargo space with the planned modules fitted (some modules shrink the hold), after your empire cargo bonus. The same value get_ship reports as cargo_capacity once the fit is in place
     */
    cargo_capacity: number;
    /**
     * Cargo space your hold uses right now, including field workshop escrow. The plan is invalid (cargo_capacity_exceeded) when this exceeds cargo_capacity and the plan shrinks the hold
     */
    cargo_used: number;
    /**
     * Total CPU with the planned modules fitted
     */
    cpu_capacity: number;
    /**
     * CPU the planned modules consume after your engineering efficiency bonus, as get_ship reports it. Invalid (cpu_exceeded) above cpu_capacity
     */
    cpu_used: number;
    /**
     * Fit plus injured crew aboard now. Invalid (personnel_capacity_exceeded) above effective_crew_capacity
     */
    crew: number;
    /**
     * Defense slots on the hull
     */
    defense_slots: number;
    /**
     * Planned defense modules. Invalid (no_defense_slots) above defense_slots
     */
    defense_slots_used: number;
    /**
     * Crew capacity with the planned modules fitted
     */
    effective_crew_capacity: number;
    /**
     * Marine capacity with the planned modules fitted
     */
    effective_marine_capacity: number;
    /**
     * Net fuel efficiency of the planned modules in percent. Positive cuts fuel use (at most 80), negative raises it (afterburners)
     */
    fuel_efficiency: number;
    /**
     * Fuel one jump costs with the planned fit: its speed and fuel efficiency, your hull and your skills. The same value find_route reports as fuel_per_jump once the fit is in place
     */
    fuel_per_jump: number;
    /**
     * Jumps a full fuel tank covers with the planned fit: max_fuel divided by fuel_per_jump, rounded down. In-system travel uses fuel too
     */
    jump_range: number;
    /**
     * Fit plus injured marines aboard now. Invalid (personnel_capacity_exceeded) above effective_marine_capacity
     */
    marines: number;
    /**
     * Fuel tank size with the planned modules fitted
     */
    max_fuel: number;
    /**
     * Maximum hull with the planned modules fitted (at least 1)
     */
    max_hull: number;
    /**
     * Maximum shield with the planned modules fitted
     */
    max_shield: number;
    /**
     * Total power with the planned modules fitted
     */
    power_capacity: number;
    /**
     * Power the planned modules consume after your engineering efficiency bonus. Invalid (power_exceeded) above power_capacity
     */
    power_used: number;
    /**
     * Shield recharged per tick with the planned modules fitted
     */
    shield_recharge: number;
    /**
     * Base speed with the planned modules fitted (at least 1). Crew efficiency is not applied; see get_ship operational_speed
     */
    speed: number;
    /**
     * Utility slots on the hull
     */
    utility_slots: number;
    /**
     * Planned utility and mining modules. Invalid (no_utility_slots) above utility_slots
     */
    utility_slots_used: number;
    /**
     * Weapon slots on the hull
     */
    weapon_slots: number;
    /**
     * Planned weapon modules. Invalid (no_weapon_slots) above weapon_slots
     */
    weapon_slots_used: number;
};

export type FitPreviewStep = {
    /**
     * The command to run
     */
    action: 'uninstall_mod' | 'install_mod';
    /**
     * The id to pass to the command: a fitted module instance ID for uninstall_mod, a module type ID for install_mod (the module must be in your cargo)
     */
    module_id: string;
    /**
     * Module display name
     */
    name: string;
    /**
     * True on an uninstall_mod of a module the plan keeps. A later install_mod step fits it again, so keep it in your cargo. Omitted (false) for modules the plan removes
     */
    temporary?: boolean;
    /**
     * Module type ID
     */
    type_id: string;
};

