export type GiftGoodwill = {
    /**
     * Credits of value applied to the donor's outstanding bounty with this empire before any goodwill. Credits pay at face value; goods and ships pay at need_value. Omitted when no bounty was owed.
     */
    bounty_paid?: number;
    /**
     * Bounty still owed to this empire after this gift. Omitted when none is left. While any bounty remains a gift earns no reputation.
     */
    bounty_remaining?: number;
    /**
     * Empire ID (e.g. solarian) or pirate crew ID (e.g. pirate_voss) whose standing the gift affected.
     */
    counterparty: string;
    /**
     * What the gift was worth to the recipient in credits after weighing how much they need it: more than face value for cash they are short of, goods that fill a real shortage, a hull their fleets need or a ship a pirate boss takes to fly in person; less for cash they do not need, goods beyond their needs, cheap hulls and ships a pirate crew breaks for parts (a rival boss's flagship excepted). Reported even when a pirate crew keeps a stranger's gift and it buys nothing.
     */
    need_value: number;
    /**
     * The recipient's in-character reply. The same text arrives as a private chat message from reply_from.
     */
    reply: string;
    /**
     * Who replied and signed the private message. Rank follows the outcome: a minion for hostile, cooling, bounty, stranger, unwanted and token gifts; an officer for appreciated and generous ones; the empire leader or pirate boss in person for lavish gifts, for donors they already treat as devoted friends, for expensive ships and whenever a pirate boss gets involved. A pirate crew answers a cheap ship with a minion and a mid-priced one with an officer.
     */
    reply_from: string;
    /**
     * Donor's reputation with the counterparty after the gift (-100 to 100). Includes any restoration from clearing a bounty.
     */
    reputation_after: number;
    /**
     * Donor's reputation with the counterparty before the gift (-100 to 100).
     */
    reputation_before: number;
    /**
     * reputation_after minus reputation_before. Each point above your baseline costs more than the last. Value short of the next point is banked toward your next gift and lost if you act against the recipient. Gifts count for little while an attack, kill or capture against the recipient is fresh, and hardly at all while they shoot you on sight.
     */
    reputation_change: number;
    /**
     * Outcome class that picked the reply: stranger (a pirate crew kept the gift but owes nothing to a pilot never introduced to the pirate network), bounty_partial, bounty_cleared, hostile, cooling, unwanted_items, unwanted_ship, or token/appreciated/generous/lavish/devoted followed by _credits, _items or _ship. A ship given to a pirate crew instead reports what the crew did with it: ship_scrap (no pirate design for that hull), ship_refit (rebuilt to a pirate design) or ship_pirate (a pirate-built hull) followed by _cheap, _mid or _expensive by its fitted value; or, when the boss gets involved, boss_upgrade (the boss switches to your ship because it out-fights the boss's current one), boss_hunt (the boss's flagship is in a player's hands and the boss takes your stronger ship to hunt them), boss_flagship_returned, boss_rival_flown (the boss flies another boss's flagship while his own is away from his crew) or boss_rival_scrapped, each with _cold appended when the crew does not like you. stranger, hostile and cooling still apply to ordinary pirate ship gifts.
     */
    situation: 'stranger' | 'bounty_partial' | 'bounty_cleared' | 'hostile' | 'cooling' | 'unwanted_items' | 'unwanted_ship' | 'token_credits' | 'token_items' | 'token_ship' | 'appreciated_credits' | 'appreciated_items' | 'appreciated_ship' | 'generous_credits' | 'generous_items' | 'generous_ship' | 'lavish_credits' | 'lavish_items' | 'lavish_ship' | 'devoted_credits' | 'devoted_items' | 'devoted_ship' | 'ship_scrap_cheap' | 'ship_scrap_mid' | 'ship_scrap_expensive' | 'ship_refit_cheap' | 'ship_refit_mid' | 'ship_refit_expensive' | 'ship_pirate_cheap' | 'ship_pirate_mid' | 'ship_pirate_expensive' | 'boss_upgrade' | 'boss_upgrade_cold' | 'boss_hunt' | 'boss_hunt_cold' | 'boss_flagship_returned' | 'boss_flagship_returned_cold' | 'boss_rival_flown' | 'boss_rival_flown_cold' | 'boss_rival_scrapped' | 'boss_rival_scrapped_cold';
};

