export type IntelPoi = {
    /**
     * Station base ID at this POI. Omitted when the POI has no station.
     */
    base_id?: string;
    /**
     * Station name at this POI. Omitted when the POI has no station.
     */
    base_name?: string;
    /**
     * POI class (for example metallic for a belt). Omitted when the POI has none.
     */
    class?: string;
    /**
     * True when this is a hidden deep core POI holding deposits. Access there needs a deep_core_access extractor that a pilot cannot refit below so the too-sparse cutoff never applies and these deposits always work down to zero. It is the one input to the mining lock formula that you cannot derive from a deposit's own numbers. Omitted (false) for every ordinary POI, for a hidden POI below the deep core survey tier (which mines like an ordinary POI), and for a hidden POI with no resources such as a wormhole mouth.
     */
    deep_core?: boolean;
    /**
     * POI description. Omitted when the POI has none or the entry never recorded it.
     */
    description?: string;
    /**
     * POI ID. Always a real POI of this system: a submission drops any ID that is not on the submitter's charts.
     */
    id: string;
    /**
     * POI display name.
     */
    name: string;
    /**
     * POI position in the system in AU when the entry was recorded. Zero on an old or hand-submitted entry that never recorded it.
     */
    position: Position;
    /**
     * Game tick at which a faction member's ship read this POI's resources: an Intel Center auto-sync from get_poi, successful mining or survey_system, or the live view when an online faction member is at this POI right now (then it equals current_tick). Omitted (0) when no member's ship has read the resources: a hand-submitted reading from faction_submit_intel is unverified and never carries this field. Compare it against current_tick to judge how stale the resources are.
     */
    read_at_tick?: number;
    /**
     * Resource deposits at this POI as last read. read_at_tick says when a member's ship read them; without read_at_tick they are a hand-submitted reading. Omitted when no reading exists: nobody has read this POI's ore.
     */
    resources?: Array<IntelResource>;
    /**
     * POI type as get_system shows it (for example asteroid_belt or station). On a hand-submitted entry it is whatever the submitter wrote until the server backfills it.
     */
    type: string;
};

