export type SovereignMintInputShortage = {
    /**
     * Always present. True exactly when this station manager has a public non-commission buy order for this item with remaining quantity greater than zero. False means no such order is available. Availability is a snapshot and does not guarantee enough order depth to cover quantity_missing.
     */
    buy_order_available: boolean;
    /**
     * Stable item ID of the externally procurable root input. At the Grand Exchange this normally identifies minable Trade Crystals rather than the internally produced Trade Cipher intermediate.
     */
    item_id: string;
    /**
     * Display name of item_id. Falls back to item_id when the item definition is unavailable.
     */
    name?: string;
    /**
     * Units currently present in station-manager storage and available to that recipe run.
     */
    quantity_in_storage: number;
    /**
     * Additional units needed, equal to max(quantity_required minus quantity_in_storage, 0). This entry is present only when the result is greater than zero.
     */
    quantity_missing: number;
    /**
     * Units required in station-manager storage to queue the next relevant mint-chain recipe run.
     */
    quantity_required: number;
};

export type SovereignMintInternalBlocker = {
    /**
     * Installed station facility instance responsible for this stage. Omitted when the required stage is not installed.
     */
    facility_id?: string;
    /**
     * Display name of facility_id.
     */
    facility_name?: string;
    /**
     * Stable item ID produced by this required stage.
     */
    item_id: string;
    /**
     * Display name of item_id.
     */
    name?: string;
    /**
     * Explains that station repair, construction, or restoration must return this production stage to service. For internal intermediates, the output is not a normal player supply request.
     */
    remediation: string;
    /**
     * Classification of this blocker.
     */
    stage: 'internal_intermediate' | 'sovereign_mint';
    /**
     * Why the required station production stage cannot currently run.
     */
    status: 'damaged' | 'under_construction' | 'unavailable';
};

export type SovereignMintPriceLimit = {
    /**
     * Stable item ID of an externally procurable mint input that needs replenishment.
     */
    item_id: string;
    /**
     * Lowest live public sell price in credits per unit at this station excluding the manager's own orders. Always greater than station_buy_price. Private and exhausted orders are excluded. Prices can change after this snapshot.
     */
    lowest_sell_price: number;
    /**
     * Display name of item_id. Falls back to item_id when its definition is unavailable.
     */
    name: string;
    /**
     * Highest live public non-commission station-manager buy price in credits per unit. Always positive. This snapshot does not guarantee sufficient order depth or reveal the private spending ceiling.
     */
    station_buy_price: number;
};

export type SovereignMintStatus = {
    /**
     * Required station-owned production stages that are missing or cannot currently run, including the final sovereign mint. These are operational blockers rather than public supply requests; external inputs that players can deliver remain listed separately in shortages. Omitted when all required stages are available and operational.
     */
    internal_blockers?: Array<SovereignMintInternalBlocker>;
    /**
     * Stable item ID produced by this sovereign mint.
     */
    output_item_id: string;
    /**
     * Display name of output_item_id. Falls back to output_item_id when the item definition is unavailable.
     */
    output_name?: string;
    /**
     * Needed external mint inputs whose lowest public sell price exceeds the station public buy price. Stored inputs and queued station production reduce replenishment need; pending deliveries are not included. Omitted without an observed price gap or live station bid. Existing production can continue. Ordered by item ID.
     */
    price_limits?: Array<SovereignMintPriceLimit>;
    /**
     * Supply guidance present whenever shortages or price_limits is non-empty. Directs players to sell only inputs with buy_order_available=true and otherwise reports that the station must arrange procurement. Check ordinary market listings for current prices and order depth. Internal Trade Ciphers are not normal player procurement.
     */
    remediation?: string;
    /**
     * Externally procurable root inputs insufficient to queue the next relevant mint-chain recipe run. Trade Crystals appear first when present. An intermediate made by an installed station feeder is expanded into that feeder's inputs rather than presented as a separate conjunctive bill. Omitted when no root input is short.
     */
    shortages?: Array<SovereignMintInputShortage>;
    /**
     * Why authenticator production needs attention: blocked_inputs when one or more external root inputs are short, or blocked_internal when a required station-owned production stage — including the final sovereign mint — is missing or cannot run. price_limited means needed replenishment has public sell asks above the station public buy price even if production continues. This observed gap does not identify a private economic ceiling.
     */
    status: 'blocked_inputs' | 'blocked_internal' | 'price_limited';
};

export type StationConfigResponse = {
    /**
     * The station action that ran, lower-cased. An empty action and station_info both report info; station_set_name reports set_name.
     */
    action: string;
    /**
     * True when non-members may build their own facilities at this station; those tenants pay rent each facility cycle to the owning faction's treasury. False means only the owning faction and its members may build.
     */
    allow_outsider_facilities: boolean;
    /**
     * Faction IDs whose members may dock while public_access is false. Omitted when the list is empty.
     */
    allowed_factions?: Array<string>;
    /**
     * Player IDs that may dock while public_access is false. player_usernames gives their names. Omitted when the list is empty.
     */
    allowed_players?: Array<string>;
    /**
     * True when the station buys fuel from any docked pilot at live scarcity-based prices, paid from the owning faction treasury and capped to what it can afford. False by default.
     */
    auto_buy_fuel: boolean;
    /**
     * Player IDs that may never dock here, even when public_access is true or they are faction members. player_usernames gives their names. Omitted when the list is empty.
     */
    banned_players?: Array<string>;
    /**
     * ID of the station or outpost you are docked at and administering.
     */
    base_id: string;
    /**
     * Custom banned item IDs in sorted order. Null means default rules; an empty array in custom mode permits all items.
     */
    contraband_items: Array<string> | null;
    /**
     * default uses the general contraband rules; custom replaces them with contraband_items at this player-owned station or mobile base. Empire customs remain unchanged.
     */
    contraband_mode: string;
    /**
     * Owner-set description, up to 500 characters. Omitted when none is set.
     */
    description?: string;
    /**
     * Present only when this outpost is one end of a jump gate. Omitted for every other station and outpost.
     */
    gate?: GateStatus;
    /**
     * Market listing fee at this station in basis points (100 = 1%, max 1000). Omitted (0) when the station uses the default rate.
     */
    market_fee_bps?: number;
    /**
     * Human-readable result of the change. Omitted for info.
     */
    message?: string;
    /**
     * Current display name of the station or outpost.
     */
    name: string;
    /**
     * Username for each player id in allowed_players and banned_players, keyed by player id. An id with no key belongs to an account that no longer exists. Omitted when both lists are empty.
     */
    player_usernames?: {
        [key: string]: string;
    };
    /**
     * True when any pilot not in banned_players may dock. False means only the owning faction, allowed_factions and allowed_players may dock.
     */
    public_access: boolean;
    /**
     * Fixed refuel price in credits per fuel unit (max 1000). Omitted (0) when the station uses the default dynamic fuel price.
     */
    refuel_price_each?: number;
    /**
     * Repair price in credits per hull point (max 10000) before any Damage Control Station discount. Omitted (0) when the station uses the default repair price.
     */
    repair_price_per_hull?: number;
    /**
     * Per-service access limits, keyed by service (market, refuel, repair, shipyard, crafting, salvage_yard). allies: the owning faction and its allies only. faction: the owning faction only. A missing key means the service is open to every docked pilot. Omitted when no service is limited.
     */
    service_access?: {
        [key: string]: string;
    };
};

