export type StationServicePoolStatus = {
    /**
     * Maximum units held by this service pool.
     */
    capacity: number;
    /**
     * Current credits per crew patient. Present for a medical pool. Covers supply cost or the configured minimum if higher. Treatment recalculates this price when executed.
     */
    crew_treatment_price?: number;
    /**
     * Current credits per marine patient. Present for a medical pool. Covers supply cost or the configured minimum if higher. Treatment recalculates this price when executed.
     */
    marine_treatment_price?: number;
    /**
     * Whole supply items needed for the next refill. Omitted when no supplies are needed.
     */
    next_cycle_supply_required?: number;
    /**
     * Maximum units replenished per facility cycle when fully supplied.
     */
    refill_per_cycle: number;
    /**
     * Units currently available to all visitors. Zero means this service pool is exhausted.
     */
    remaining: number;
    /**
     * Item consumed to replenish this pool. Omitted when no supply item is configured.
     */
    supply_item?: string;
};

export type StationServicePools = {
    /**
     * Marines available to train here from the station's best operational marine training facility. Omitted when the station has none.
     */
    marine_training?: StationServicePoolStatus;
    /**
     * Patients the station can treat here from its best operational medical facility, with crew_treatment_price and marine_treatment_price. Omitted when the station has none.
     */
    medical?: StationServicePoolStatus;
    /**
     * Crew recruits available to hire here from the station's best operational personnel facility. Omitted when the station has none.
     */
    personnel?: StationServicePoolStatus;
};

