/**
 * Summary of a point of interest within a system.
 */
export type SystemPoi = {
    base_id?: string;
    base_name?: string;
    /**
     * Kind of base at this POI. station is a full station (empire or player-built). outpost is a faction outpost: a members-only storage and fuel depot. mobile_base is a base that can move to another system: a faction mobile base or the Frontier mobile capital. Omitted when has_base is false.
     */
    base_type?: 'station' | 'outpost' | 'mobile_base';
    /**
     * Type-specific classification for client rendering (e.g. star spectral class, planet type, belt composition)
     */
    class?: string;
    has_base?: boolean;
    /**
     * Environmental hazard at this POI. Omitted when there is none. Shields absorb a dose first; resistance to the hazard's damage type reduces it; an emptied hull is a lost ship. Docked, offline and in-battle pilots are not dosed.
     */
    hazard?: {
        /**
         * 1 low, 2 moderate, 3 high, 4 lethal. One dose takes 1%, 3%, 8% or 25% of maximum hull before shields and resistance.
         */
        severity: number;
        /**
         * radiation (thermal), tidal_shear (kinetic) and scar_dust (kinetic) dose every tick an undocked ship stays. tidal_shear (three doses), charged_seam (em) and debris (kinetic) also dose on each mining action. charged_seam, scar_dust and ion_storm lower scan and survey power here.
         */
        type: 'radiation' | 'tidal_shear' | 'charged_seam' | 'debris' | 'scar_dust' | 'ion_storm';
    };
    id: string;
    name: string;
    /**
     * Position in AU from system center. It changes with time.
     */
    position?: {
        x?: number;
        y?: number;
    };
    /**
     * Ships your ship scanner picks up at this POI: other players that are not cloaked (online, offline, and docked alike), flying pirates, active empire NPC ships, and hatched leviathans. Your own ship and wildlife herds are not counted. Omitted when your ship has no working ship scanner (sensor rating 0); 0 means a scanner and no ships.
     */
    ship_count?: number;
    type: string;
};

