export type V2Resource = {
    /**
     * Item id of the ore, gas, ice or radioactive material in this deposit — for example iron_ore or fury_crystal.
     */
    item_id: string;
    /**
     * Display name of the resource. Falls back to the raw item id when the catalog has no entry for it.
     */
    item_name: string;
    /**
     * Stock this deposit must hold for your fitted array to keep a lock on it once the deposit falls below a quarter of capacity. Below both thresholds at once extraction fails with deposit_too_sparse. Omitted when your array can never lose a lock here — either its power adjusted for precision is at most 20, or this is a deep core POI, where the hard cutoff never applies.
     */
    lock_minimum_stock?: number;
    /**
     * Units of stock left. -1 means an unlimited deposit that never depletes; 0 means fully depleted.
     */
    remaining: number;
    /**
     * Percentage multiplier on extraction yield: yield is applied beam power times richness divided by 100, floored at 1 unit per action.
     */
    richness: number;
    /**
     * Beam power this deposit accepts at full extraction rate, computed for the extraction hardware you have fitted right now — remaining stock divided by 20 and by your array's precision factor. Power above it is capped down to it rather than wasted, so extraction continues at the reduced rate. Omitted when the deposit is depleted or unlimited.
     */
    supported_power?: number;
    /**
     * True when your currently fitted array cannot work this deposit at all right now. Omitted (false) whenever the deposit is workable.
     */
    too_sparse?: boolean;
};

/**
 * Standard v2 REST API response envelope.
 */
export type V2Response = {
    /**
     * Error details (present instead of result on failure).
     */
    error?: {
        /**
         * Machine-readable error code. Session/auth codes: session_required (no X-Session-Id header), session_invalid (session not found or expired — create a new one with POST /api/v2/session then login), not_authenticated (session exists but not logged in). Other codes: rate_limited, command_error, invalid_params, invalid_json, payload_too_large, method_not_allowed, missing_action, unknown_command. ip_timed_out is WebSocket-only: over HTTP an IP block returns a flat 429 body without this envelope: {"error": "rate_limited", "message", "retry_after", "limit": "ip_timeout", "scope": "ip"} plus a Retry-After header.
         */
        code?: string;
        /**
         * Optional structured details about the error. Always an object; its keys vary by error code. For example, `missing_materials` carries a `missing` array of {item_id, item_name, need, have} objects.
         */
        details?: {
            [key: string]: unknown;
        };
        /**
         * Human-readable error message.
         */
        message?: string;
        /**
         * Seconds to wait before retrying. Present on rate_limited errors from a rate-limit bucket (bug-report rate_limited errors omit it; the failed-login block is the failed_auth bucket, scope per_ip), with the same value in the Retry-After header. details then carries limit (the bucket), scope (what the bucket is keyed on) and, for capped buckets, limit_per_min and current.
         */
        retry_after?: number;
    };
    /**
     * Pending notifications (combat, chat, trade, etc.) accumulated since last request.
     */
    notifications?: Array<{
        /**
         * Notification payload. Shape depends on msg_type — see the Notification_* schemas under components.schemas.
         */
        data?: NotificationPayload;
        id?: string;
        /**
         * Specific message subtype used for handler routing (e.g. chat_message, battle_update, action_result, mining_yield). Switch on this to pick the matching Notification_* payload schema.
         */
        msg_type?: string;
        timestamp?: string;
        /**
         * Notification category: chat, combat, trade, market, crafting, observation, system
         */
        type?: string;
    }>;
    /**
     * Human-readable text summary when a renderer is available, otherwise the raw result data.
     */
    result?: unknown;
    /**
     * Current session info.
     */
    session?: {
        created_at?: string;
        expires_at?: string;
        id?: string;
        player_id?: string;
    };
    /**
     * Raw structured JSON data for programmatic access. Always present for successful game commands.
     */
    structuredContent?: {
        [key: string]: unknown;
    };
};

