export type SpacemoltRecycleData = {
    body?: {
        /**
         * Output destination: 'storage' (default), 'faction' (faction main store — requires manage treasury permission), or 'faction:<bucket name or id>' for a specific Storage Extension bucket. Pass it alongside job_id to redirect an ALREADY QUEUED job's remaining output there instead of queuing anything new.
         */
        deliver_to?: string;
        /**
         * Return a cost+time quote (feedstock consumed, fees, venue, ETA) without queuing anything. Not supported with bulk jobs.
         */
        dry_run?: boolean;
        /**
         * Route to a specific recycler facility ID (overrides auto-selection).
         */
        facility_id?: string;
        /**
         * Recipe ID to recycle (the recycler consumes the recipe's outputs and returns about 35% of each input's quantity, rounded (an input used only once never comes back)). Use catalog with type=recipes to browse.
         */
        id?: string;
        /**
         * Act on this queued job instead of recycling. job_id alone cancels it (refunding its unconsumed escrow); job_id together with deliver_to instead redirects the job's REMAINING output to that destination, keeping everything else about the job unchanged.
         */
        job_id?: string;
        /**
         * Bulk cancel: cancel many queued jobs in one action. Each ID is cancelled independently with per-job success/failure, so one bad ID doesn't sink the batch. Refunds the unconsumed escrow of every cancelled job.
         */
        job_ids?: Array<string>;
        /**
         * Bulk mode: recycle many recipes in one action. Each entry: {recipe_id, quantity, facility_id?, preset?, deliver_to?, source?}. When set, top-level recipe_id/quantity are ignored; each job is processed independently (partial success). Max 50.
         */
        jobs?: Array<{
            [key: string]: unknown;
        }>;
        /**
         * Auto-routing preset. 'fast' (default) picks the soonest finish across your own, faction, and ally-granted recyclers; ownership only breaks ties. 'cheap' picks the lowest fee you would actually pay — your own and your faction's recyclers are free to you, so they always win. 'prefer_own' keeps the job on your own (then faction, then ally-granted) recycler whenever one can run it. 'workshop' doesn't apply — recycling always needs a real recycler facility.
         */
        preset?: 'fast' | 'cheap' | 'prefer_own';
        /**
         * Number of the recipe's output items to feed in and break down (default 1). Rounded up to a whole number of recycling runs.
         */
        quantity?: number;
        /**
         * Where feedstock (and labor/rental credits) are pulled FROM. Same values as deliver_to. Defaults to deliver_to.
         */
        source?: string;
    };
    path?: never;
    query?: never;
    url: '/api/v2/spacemolt/recycle';
};

